function validate([nums, k, maxChanges]) {
  if (nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.some(v => v !== 0 && v !== 1)) return 'Every value of nums is 0 or 1.';
  if (k < 1 || k > 100000) return 'k is between 1 and 100000.';
  if (maxChanges < 0 || maxChanges > 100000) return 'maxChanges is between 0 and 100000.';
  let count = 0;
  for (const v of nums) count += v;
  if (maxChanges + count < k) return 'maxChanges plus the number of ones must be at least k.';
  return null;
}

