function minimumMoves(nums, k, maxChanges) {
  const ones = [];
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === 1) ones.push(i);
  }
  const prefix = [0];
  for (const position of ones) {
    prefix.push(prefix[prefix.length - 1] + position);
  }

  const fewest = Math.max(0, k - maxChanges);
  const most = Math.min(k, ones.length, fewest + 3);
  let best = fewest === 0 ? 2 * k : Infinity;

  for (let size = Math.max(1, fewest); size <= most; size++) {
    for (let left = 0; left + size <= ones.length; left++) {
      const right = left + size;
      const mid = left + Math.floor(size / 2);
      const pullLeft = ones[mid] * (mid - left) - (prefix[mid] - prefix[left]);
      const pullRight = prefix[right] - prefix[mid] - ones[mid] * (right - mid);
      best = Math.min(best, pullLeft + pullRight + 2 * (k - size));
    }
  }
  return best;
}

