function minimumMoves(nums, k, maxChanges) {
  // Breadth-first search over the real game: (board, collected, creates used) for every starting cell.
  const n = nums.length;
  let best = Infinity;
  for (let alice = 0; alice < n; alice++) {
    let board = 0;
    for (let i = 0; i < n; i++) if (nums[i] === 1 && i !== alice) board |= 1 << i;
    const start = nums[alice] === 1 ? 1 : 0;
    if (start === k) { best = 0; continue; }
    const seen = new Set([board + ',' + start + ',0']);
    let frontier = [[board, start, 0]];
    let depth = 0;
    search: while (frontier.length && depth < best) {
      depth++;
      const next = [];
      for (const [b, got, used] of frontier) {
        const options = [];
        if (used < maxChanges) for (let j = 0; j < n; j++) if (j !== alice && !((b >> j) & 1)) options.push([b | (1 << j), got, used + 1]);
        for (let x = 0; x < n; x++) {
          if (!((b >> x) & 1)) continue;
          for (const y of [x - 1, x + 1]) {
            if (y < 0 || y >= n || ((b >> y) & 1)) continue;
            const moved = (b & ~(1 << x)) | (1 << y);
            options.push(y === alice ? [moved & ~(1 << y), got + 1, used] : [moved, got, used]);
          }
        }
        for (const option of options) {
          if (option[1] === k) { best = Math.min(best, depth); break search; }
          const id = option.join(',');
          if (!seen.has(id)) { seen.add(id); next.push(option); }
        }
      }
      frontier = next;
    }
  }
  return best;
}

