function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 6);
  const density = rand();
  const nums = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  let maxChanges;
  if (size === 'large') maxChanges = rand() < 0.6 ? Math.floor(rand() * 20) : Math.floor(rand() * 100001);
  else maxChanges = rand() < 0.2 ? 100000 : Math.floor(rand() * 4);
  let count = nums.reduce((a, b) => a + b, 0);
  if (count + maxChanges === 0) {
    nums[Math.floor(rand() * n)] = 1;
    count = 1;
  }
  const cap = Math.min(size === 'large' ? 100000 : 5, count + maxChanges);
  // Large inputs with few creates aim k at the ones on the board, where the window search matters.
  const k = size === 'large' && maxChanges < 20 && rand() < 0.7 ? Math.max(1, Math.min(cap, maxChanges + 1 + Math.floor(rand() * count))) : 1 + Math.floor(rand() * cap);
  return [nums, k, maxChanges];
}
